private static let agentPath = Bundle.main.executableURL?
    .deletingLastPathComponent()
    .appendingPathComponent("myterm-agent").path

/// 진행 중인 작업이 있으면 새 명령을 받지 않는다 (사용자 확인 대기는 제외).
var isBusy: Bool { jobs.contains { !$0.isFinished && !$0.isWaitingForUser } }

init(workspace: URL, claude: TerminalSession, codex: TerminalSession, settings: AgentSettings) {
    self.workspace = workspace
    self.claude = claude
    self.codex = codex
    self.settings = settings
    reload()
    selectedJobId = jobs.last { !$0.isFinished && !$0.isWaitingForUser }?.id
    startLoopIfNeeded()
}

/// 새 카드를 연다. 돌고 있는 작업이 있어도 새 터미널처럼 함께 진행한다
/// (리뷰 · 커밋은 각 작업이 고친 파일로 좁혀지고, Smart JIRA 는 파일이 겹치면 스스로 줄을 선다).
private func reload() {
    let directories = (try? FileManager.default.contentsOfDirectory(
        at: jobsDirectory,
        includingPropertiesForKeys: nil
    )) ?? []
    jobs = directories
        .compactMap(JobSnapshot.load)
        .sorted { $0.id < $1.id }
    jobs.forEach(writeReviewDocuments)
}

private func refresh(_ id: String) {
    guard let index = jobs.firstIndex(where: { $0.id == id }),
          let fresh = JobSnapshot.load(jobs[index].files.directory)
    else { return }
    jobs[index] = fresh
    writeReviewDocuments(fresh)
}

private func startLoopIfNeeded() {
    guard loop == nil, isBusy else { return }
    loop = Task { [weak self] in
        while !Task.isCancelled {
            guard let self, self.isBusy else { break }
            self.tick()
            try? await Task.sleep(for: .seconds(1))
        }
        self?.loop = nil
    }
}

private func tick() {
    for job in jobs where !job.isFinished {
        advance(job)
        refresh(job.id)
    }
    for job in jobs { updateLive(job) }
}

